const TAIL = {{tail}} / 100, SLOW = {{slow}};
const data = Array.from({ length: 2000 }, () => (Math.random() < TAIL ? SLOW * (0.6 + Math.random() * 0.8) : 60 + Math.random() * 120));
data.sort((a, b) => a - b);
const pick = (q) => data[Math.floor(q * (data.length - 1))];
const mean = data.reduce((s, v) => s + v, 0) / data.length;
ctx.clearRect(0, 0, W(), H());
const max = data[data.length - 1];
data.forEach((v, i) => {
  if (i % 4) return;
  const x = 16 + (i / data.length) * (W() - 32);
  const h = (v / max) * (H() - 90);
  ctx.fillStyle = v > 1000 ? '#f87171' : '#60a5fa';
  ctx.fillRect(x, H() - 30 - h, 2, h);
});
ctx.fillStyle = '#eee'; ctx.font = '14px system-ui';
ctx.fillText('평균 ' + Math.round(mean) + 'ms  ·  p50 ' + Math.round(pick(0.5)) + '  ·  p95 ' + Math.round(pick(0.95)) + '  ·  p99 ' + Math.round(pick(0.99)), 16, 24);
ctx.fillStyle = '#9ca3af'; ctx.font = '12px system-ui';
ctx.fillText('빨간 막대가 사람들이 화내는 그 요청이다', 16, 46);
